from datetime import datetime
from pathlib import Path
import shutil

from docx import Document
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml.ns import qn
from docx.shared import Cm, Pt, RGBColor


DOCX = Path("bagiin_ner_v29.docx")
BACKUP_DIR = Path("output/docx_backups")
BACKUP_DIR.mkdir(parents=True, exist_ok=True)


def clear_runs(paragraph):
    for run in list(paragraph.runs):
        run._element.getparent().remove(run._element)


def set_text(paragraph, text, *, bold=False, italic=False, size=12,
             align=WD_ALIGN_PARAGRAPH.JUSTIFY, first_line=True):
    clear_runs(paragraph)
    run = paragraph.add_run(text)
    run.font.name = "Times New Roman"
    run._element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
    run.font.size = Pt(size)
    run.font.bold = bold
    run.font.italic = italic
    run.font.color.rgb = RGBColor(0, 0, 0)

    paragraph.alignment = align
    paragraph.paragraph_format.line_spacing = 1.5
    paragraph.paragraph_format.space_before = Pt(0)
    paragraph.paragraph_format.space_after = Pt(6)
    paragraph.paragraph_format.first_line_indent = Cm(1.25) if first_line else Cm(0)


def norm(text):
    return " ".join(text.split())


def replace_exact(paragraphs, old, new):
    for paragraph in paragraphs:
        if norm(paragraph.text) == old:
            set_text(paragraph, new)
            return True
    return False


backup = BACKUP_DIR / f"bagiin_ner_v29_before_threshold_interpretation_{datetime.now():%Y%m%d_%H%M%S}.docx"
shutil.copy2(DOCX, backup)

